window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[1]={"id":"001","numero":1,"titre":"Relation médecin-malade","objectifs":[{"id":"1-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la relation médecin-malade","contenu":"<p>La <strong><span class=\"kw-def\">relation médecin-malade</span></strong> est une <strong><span class=\"kw-def\">relation interpersonnelle</span></strong> qui implique plusieurs acteurs (<span class=\"kw-clinique\">médecin</span>, <span class=\"kw-clinique\">soignants</span>, <span class=\"kw-clinique\">patient</span>, <span class=\"kw-clinique\">entourage</span>) et qui se noue <strong>autour de la maladie</strong>. Elle est caractérisée par des <strong><span class=\"kw-def\">attentes mutuelles</span></strong>, un <strong><span class=\"kw-def\">investissement affectif</span></strong>, et se déroule dans un <span class=\"kw-def\">cadre socio-culturel et éthique</span>.</p>\n\n<div class=\"callout callout-info\">Trait fondamental : cette relation est par nature <strong><span class=\"kw-def\">asymétrique</span></strong> — médecin et malade diffèrent sur plusieurs plans. Comprendre cette <span class=\"kw-clinique\">asymétrie</span> est la clé d'une communication et d'une prise en charge de qualité.</div>\n\n<h4 class=\"kw-def\"><span class=\"kw-clinique\">Les</span> cinq axes de l'<span class=\"kw-clinique\">asymétrie</span></h4>\n<table >\n  <thead><tr><th>Axe</th><th>Malade</th><th>Médecin</th></tr></thead>\n  <tbody>\n    <tr>\n      <td><strong>Représentation de la maladie</strong></td>\n      <td>Expertise du <span class=\"kw-clinique\">vécu</span> de sa maladie</td>\n      <td>Expertise <span class=\"kw-bio\">médicale</span> et savoir <span class=\"kw-def\">scientifique</span> (aspects objectifs)</td>\n    </tr>\n    <tr>\n      <td><strong>Représentation de la santé</strong></td>\n      <td>Santé = <span class=\"kw-def\">moyen au service de la qualité de vie</span></td>\n      <td>Santé = <span class=\"kw-def\">absence de maladie</span></td>\n    </tr>\n    <tr>\n      <td><strong>Position</strong></td>\n      <td><span class=\"kw-alerte\">Position de faiblesse</span> : vulnérabilité, handicap, dépendance</td>\n      <td>Position de force : maîtrise du savoir, pouvoir <span class=\"kw-def\">diagnostique</span> et décisionnel</td>\n    </tr>\n    <tr>\n      <td><strong>Peur</strong></td>\n      <td>Redoute la <span class=\"kw-clinique\">maladie</span>, le handicap, la dépendance, la <span class=\"kw-clinique\">mort</span></td>\n      <td>Redoute l'<span class=\"kw-clinique\">échec</span>, l'<span class=\"kw-clinique\">erreur diagnostique</span>, la maladie grave à annoncer</td>\n    </tr>\n    <tr>\n      <td><strong>Attente</strong></td>\n      <td>Savoir, guérison, <span class=\"kw-clinique\">soulagement de la douleur</span>, reconnaissance de sa <span class=\"kw-alerte\">détresse</span></td>\n      <td>Reconnaissance de sa valeur professionnelle, acceptation des décisions</td>\n    </tr>\n  </tbody>\n</table>\n\n<h4 class=\"kw-def\">Ce dont dépend la relation</h4>\n<ul>\n  <li>De la <strong><span class=\"kw-etio\">maladie</span></strong> elle-même : <span class=\"kw-clinique\">gravité</span>, <span class=\"kw-clinique\">chronicité</span>, <span class=\"kw-clinique\">évolutivité</span>.</li>\n  <li>Des <strong><span class=\"kw-etio\">réactions psychologiques du patient</span></strong> et de son entourage face à la maladie.</li>\n  <li>Des <strong><span class=\"kw-etio\">réactions psychologiques du médecin</span></strong> et des soignants face aux situations rencontrées.</li>\n  <li>Des <strong><span class=\"kw-def\">déterminants de la qualité de la relation</span></strong>, utiles pour guider l'<span class=\"kw-def\">annonce</span> d'une <span class=\"kw-alerte\">mauvaise nouvelle</span>.</li>\n</ul>\n\n<p>L'<span class=\"kw-clinique\">asymétrie</span> est <strong>inévitable mais essentielle</strong> : fondée sur des savoirs différents et un enjeu émotionnel fort, elle structure toute la rencontre de soin.</p>","frequence":0},{"id":"1-2","rang":"A","rubrique":"Définition","titre":"Connaître les principaux déterminants de la relation médecin-malade","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">déterminants de la relation</span></strong> décrivent la répartition des <strong>rôles actif / passif</strong> du médecin et du patient, et le <strong>niveau d'implication</strong> attendu du malade. On distingue classiquement <span class=\"kw-def\">quatre types de relation</span> et <span class=\"kw-def\">trois modèles de décision</span>.</p>\n\n<h4 class=\"kw-def\"><span class=\"kw-clinique\">Les</span> 4 types de relation (selon l'implication du patient)</h4>\n<table >\n  <thead><tr><th>Type</th><th>Implication du patient</th><th>Exemple</th></tr></thead>\n  <tbody>\n    <tr>\n      <td><strong><span class=\"kw-def\">Activité / passivité</span></strong></td>\n      <td>Patient <span class=\"kw-clinique\">passif</span>, aucune activité ; le médecin agit seul — adaptée aux <span class=\"kw-alerte\">maladies aiguës graves</span></td>\n      <td>Acte chirurgical, <span class=\"kw-clinique\">coma</span>, <span class=\"kw-alerte\">réanimation</span></td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Consensuelle</span></strong></td>\n      <td>Acceptation et coopération d'un patient <strong>déjà convaincu</strong> de la nécessité de la prise en charge</td>\n      <td>Pose d'un plâtre</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Coopérative</span></strong></td>\n      <td>Coopération d'un patient <strong>à convaincre</strong> : le médecin doit expliquer la nécessité du geste</td>\n      <td>Examen gynécologique, soins dentaires</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Participative</span></strong></td>\n      <td>Patient = <strong>acteur privilégié</strong> de la guérison (relation « autonomiste ») — adaptée aux <span class=\"kw-alerte\">maladies chroniques</span></td>\n      <td>Changement de <span class=\"kw-clinique\">mode de vie</span> et d'habitudes</td>\n    </tr>\n  </tbody>\n</table>\n\n<h4 class=\"kw-def\"><span class=\"kw-clinique\">Les</span> 3 modèles de décision</h4>\n<table >\n  <thead><tr><th>Modèle</th><th>Information / décision</th><th>Indications</th></tr></thead>\n  <tbody>\n    <tr>\n      <td><strong><span class=\"kw-def\">Paternaliste</span></strong></td>\n      <td><strong>Information :</strong> <span class=\"kw-clinique\">unidirectionnelle</span> (médecin → patient)<br><strong>Décision :</strong> <span class=\"kw-clinique\">médecin seul</span></td>\n      <td><span class=\"kw-alerte\">Urgence</span>, patient <span class=\"kw-clinique\">inconscient</span> ou incapable de décider</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Décision partagée</span></strong></td>\n      <td><strong>Information :</strong> <span class=\"kw-clinique\">bidirectionnelle</span> (médecin ↔ patient)<br><strong>Décision :</strong> <span class=\"kw-clinique\">médecin et patient ensemble</span></td>\n      <td><span class=\"kw-etio\">Maladies chroniques</span> ; plusieurs options thérapeutiques possibles</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Informatif</span></strong></td>\n      <td><strong>Information :</strong> unidirectionnelle (médecin → patient)<br><strong>Décision :</strong> <span class=\"kw-clinique\">patient seul</span></td>\n      <td>Patient <span class=\"kw-def\">expert</span>, très autonome ; maladies rares</td>\n    </tr>\n  </tbody>\n</table>\n\n<p>Deux variantes intermédiaires existent : le <strong><span class=\"kw-def\">modèle interprétatif</span></strong> (le médecin aide le patient à expliciter ses <span class=\"kw-clinique\">valeurs</span> puis oriente la décision) et le <strong><span class=\"kw-def\">modèle délibératif</span></strong> (le médecin accompagne activement l'élaboration du point de vue du patient).</p>\n\n<div class=\"callout callout-warn\">⚠️ <strong>Pièges des modèles extrêmes :</strong> le paternalisme peut être <span class=\"kw-alerte\">infantilisant</span> et réduire l'adhésion thérapeutique ; le modèle informatif expose à une <span class=\"kw-alerte\">décision inadaptée</span> si le patient manque d'informations. L'idéal est d'<strong>adapter le modèle au contexte et aux préférences</strong> du patient.</div>","frequence":0},{"id":"1-3","rang":"A","rubrique":"Définition","titre":"Connaître les principaux corrélats cliniques de la relation médecin-malade","contenu":"<p>Du fait de son <strong><span class=\"kw-def\">asymétrie</span></strong>, la relation médecin-malade s'accompagne de <strong><span class=\"kw-def\">corrélats cliniques</span></strong> de nature affective : le <strong><span class=\"kw-def\">transfert</span></strong> et le <strong><span class=\"kw-def\">contre-transfert</span></strong>. Largement <span class=\"kw-clinique\">inconscients</span>, ils réactivent des modalités relationnelles de l'enfance et influencent la décision comme l'observance.</p>\n\n<h4 class=\"kw-def\">Transfert — investissement affectif du patient vers le médecin</h4>\n<p>Le <strong><span class=\"kw-def\">transfert</span></strong> désigne tout <strong>investissement affectif du patient sur le médecin</strong>. Il dépend des <span class=\"kw-etio\">représentations</span>, des <span class=\"kw-etio\">attentes</span> et du <span class=\"kw-etio\">style d'attachement</span> du patient :</p>\n<ul>\n  <li><strong><span class=\"kw-def\">Transfert positif</span></strong> : sentiment de <span class=\"kw-clinique\">sympathie</span> et de <span class=\"kw-clinique\">confiance</span> envers le médecin.</li>\n  <li><strong><span class=\"kw-def\">Transfert négatif</span></strong> : sentiment d'<span class=\"kw-clinique\">antipathie</span> et de <span class=\"kw-clinique\">méfiance</span>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Contre-transfert — investissement affectif du médecin vers le patient</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Contre-transfert positif</span></strong> : médecin <span class=\"kw-clinique\">attentif</span> au patient ; <span class=\"kw-alerte\">risque</span> de perdre l'<span class=\"kw-clinique\">objectivité</span> nécessaire aux décisions difficiles s'il l'est trop.</li>\n  <li><strong><span class=\"kw-def\">Contre-transfert négatif</span></strong> : attitudes de <span class=\"kw-clinique\">rejet</span> — <span class=\"kw-alerte\">refus d'écoute</span>, <span class=\"kw-alerte\">décision prise trop rapidement</span>.</li>\n</ul>\n\n<div class=\"callout callout-info\">Reconnaître son propre <strong>contre-transfert</strong> est une compétence clinique : il conditionne la <strong><span class=\"kw-def\">qualité du lien</span></strong> et la justesse des décisions, notamment face à un patient difficile.</div>","frequence":0},{"id":"1-4","rang":"A","rubrique":"Définition","titre":"Connaître les principes de « l’approche centrée sur le patient »","contenu":"<p>L'<strong><span class=\"kw-def\">approche centrée sur le patient</span></strong> place le malade au cœur des décisions qui le concernent. Elle s'incarne dans le <strong><span class=\"kw-def\">modèle de décision médicale partagée</span></strong>, fondé sur le <strong>respect de la personne</strong> et sa participation aux choix de santé.</p>\n\n<h4 class=\"kw-def\">Principes de la décision médicale partagée</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Échange bilatéral</span></strong> d'information : à la fois <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">preuves scientifiques</span> et les <span class=\"kw-def\">valeurs et préférences</span> du patient.</li>\n  <li><strong><span class=\"kw-def\">Délibération commune</span></strong> aboutissant à une décision <strong>acceptée d'un commun accord</strong>.</li>\n  <li>Cadre légal : <strong><span class=\"kw-def\">loi du 4 mars 2002</span></strong> — toute personne prend, avec le professionnel, <span class=\"kw-clinique\">les</span> décisions concernant sa santé ; <span class=\"kw-ci\">aucun acte sans consentement libre et éclairé</span>, retirable à tout moment.</li>\n</ul>\n\n<h4 class=\"kw-def\">Mise en œuvre (4 étapes)</h4>\n<ul>\n  <li>Établir une <strong>atmosphère propice</strong> à l'échange, où l'opinion du patient est prise en compte.</li>\n  <li>Rechercher <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-clinique\">préférences</span></strong> du patient sur les différentes options.</li>\n  <li>Échanger <span class=\"kw-clinique\">les</span> informations : <span class=\"kw-def\">options</span> (dont celle de <strong>ne pas traiter</strong>), <span class=\"kw-clinique\">bénéfices</span> et <span class=\"kw-alerte\">risques</span> ; recueillir les <span class=\"kw-etio\">représentations</span> et valeurs du patient.</li>\n  <li>Trouver un <strong>accord mutuel</strong> et prendre une décision ensemble.</li>\n</ul>\n\n<h4 class=\"kw-def\">Intégrer la perspective et <span class=\"kw-clinique\">les</span> ressources du patient</h4>\n<p>L'approche centrée sur le patient suppose de prendre en compte sa <strong><span class=\"kw-def\">théorie profane</span></strong> et <span class=\"kw-clinique\">les</span> facteurs contextuels qui lui sont propres :</p>\n<ul>\n  <li><strong>Perspective :</strong> <span class=\"kw-etio\">conceptions culturelles</span> ; convictions spirituelles ; <span class=\"kw-clinique\">état de santé ressenti</span> ; attitude envers la maladie ; <span class=\"kw-clinique\">priorités de santé</span>.</li>\n  <li><strong>Ressources :</strong> <span class=\"kw-etio\">ressources financières</span> ; accès aux soins ; ressources <span class=\"kw-etio\">cognitives</span> et <span class=\"kw-etio\">émotionnelles</span> ; <span class=\"kw-def\">soutien socio-familial</span>.</li>\n</ul>\n\n<div class=\"callout callout-info\"><span class=\"kw-clinique\">Les</span> <strong>systèmes d'aide à la décision</strong> (documents, vidéos) <strong>accompagnent</strong> sans remplacer le médecin : ils aident le patient à révéler ses <span class=\"kw-clinique\">valeurs</span>. Le partage de la décision <strong>ne modifie pas la responsabilité médicale</strong>.</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"1-5","rang":"A","rubrique":"Définition","titre":"Connaître la notion de représentation de la maladie","contenu":"<p>La <strong><span class=\"kw-def\">représentation de la maladie</span></strong> est la manière dont chaque acteur se figure la maladie. Patient et médecin en ont une <strong>vision différente</strong>, à l'origine de l'<span class=\"kw-def\">asymétrie</span> de la relation.</p>\n\n<table >\n  <thead><tr><th></th><th>Patient</th><th>Médecin</th></tr></thead>\n  <tbody>\n    <tr>\n      <td><strong>Représentation de la maladie</strong></td>\n      <td>Expertise du <strong><span class=\"kw-clinique\">vécu</span></strong> subjectif de sa maladie</td>\n      <td>Expertise <span class=\"kw-bio\">médicale</span>, savoir <span class=\"kw-def\">scientifique</span> sur <span class=\"kw-clinique\">les</span> aspects <strong>objectifs</strong></td>\n    </tr>\n    <tr>\n      <td><strong>Représentation de la santé</strong></td>\n      <td>Santé = <span class=\"kw-def\">moyen au service de la qualité de vie</span></td>\n      <td>Santé = <span class=\"kw-def\">absence de maladie</span></td>\n    </tr>\n  </tbody>\n</table>\n\n<h4 class=\"kw-def\">Théorie profane <span class=\"kw-bio\">vs</span> théorie savante</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Théorie savante</span></strong> (médecin) : déterminée par <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">recommandations fondées sur les preuves</span> concernant le trouble.</li>\n  <li><strong><span class=\"kw-def\">Théorie profane</span></strong> (patient) : ses <span class=\"kw-etio\">représentations</span>, <span class=\"kw-etio\">croyances</span>, <span class=\"kw-etio\">affects</span> et <span class=\"kw-etio\">motivations</span> propres face à la maladie.</li>\n</ul>\n\n<p>La représentation conditionne ce que le patient <strong><span class=\"kw-clinique\">comprend</span></strong> et <strong><span class=\"kw-clinique\">accepte</span></strong> de l'information, ses <span class=\"kw-def\">stratégies de coping</span> et son <span class=\"kw-clinique\">adhésion</span> au traitement. La <strong><span class=\"kw-def\">décision thérapeutique</span></strong> naît de la <strong>confrontation</strong> entre théorie savante et théorie profane.</p>\n\n<div class=\"callout callout-info\">Identifier la <strong>théorie profane</strong> du patient — représentations, affects, motivations, transfert, mécanismes de défense — fait partie du <span class=\"kw-def\">processus d'engagement</span> clinique et de l'évaluation initiale.</div>","frequence":0},{"id":"1-6","rang":"A","rubrique":"Définition","titre":"Connaître les facteurs influençant l’information délivrée au patient","contenu":"<p>L'<strong><span class=\"kw-def\">information délivrée au patient</span></strong> est un <strong>transfert bidirectionnel</strong> dont le contenu et la forme sont modulés par des facteurs liés au <strong>médecin</strong>, au <strong>patient</strong>, à la <strong>maladie</strong> et au <strong>contexte</strong>.</p>\n\n<h4 class=\"kw-def\">Facteurs liés au médecin</h4>\n<p>Le <strong><span class=\"kw-def\">contre-transfert</span></strong> et <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-def\">mécanismes de défense</span></strong> du médecin peuvent <span class=\"kw-alerte\">distordre ou retenir</span> l'information :</p>\n<ul>\n  <li><strong><span class=\"kw-def\">Mensonge</span></strong> (par omission le plus souvent) : sous l'alibi de protéger le patient, le médecin se protège surtout lui-même — <span class=\"kw-alerte\">effets délétères, à prohiber</span>.</li>\n  <li><strong><span class=\"kw-def\">Rationalisation</span></strong> : refuge derrière un discours <span class=\"kw-clinique\">technoscientifique</span> hermétique, incompréhensible.</li>\n  <li><strong><span class=\"kw-def\">Fausse réassurance</span></strong> : entretient un <span class=\"kw-alerte\">espoir disproportionné</span> aux données factuelles.</li>\n  <li><strong><span class=\"kw-def\">Fuite en avant</span></strong> : information délivrée « à marche forcée », surestimant <span class=\"kw-clinique\">les</span> capacités du patient.</li>\n</ul>\n\n<h4 class=\"kw-def\">Facteurs liés au patient</h4>\n<ul>\n  <li>Ce qu'il <strong><span class=\"kw-clinique\">sait déjà</span></strong>, ce qu'il <strong><span class=\"kw-clinique\">souhaite savoir</span></strong> et ce qu'il <strong><span class=\"kw-clinique\">doit savoir</span></strong>.</li>\n  <li>Ses <span class=\"kw-etio\">représentations</span> et sa <strong><span class=\"kw-def\">théorie profane</span></strong>.</li>\n  <li>Ses <span class=\"kw-clinique\">réactions affectives</span> et ses <strong><span class=\"kw-def\">mécanismes de défense</span></strong> (déni, isolation…), qui filtrent la réception.</li>\n</ul>\n\n<h4 class=\"kw-def\">Modalités d'une information de qualité</h4>\n<ul>\n  <li>Délivrer l'information <strong><span class=\"kw-clinique\">progressivement</span></strong>, au rythme du patient.</li>\n  <li>Vocabulaire <strong>approprié</strong>, <span class=\"kw-ci\">sans jargon ni euphémisme</span>.</li>\n  <li>Vérifier la compréhension par la <strong><span class=\"kw-clinique\">reformulation</span></strong> du patient.</li>\n</ul>\n\n<div class=\"callout callout-warn\">⚠️ Le <strong>mensonge</strong> n'a que des <span class=\"kw-alerte\">effets délétères</span> et devrait être prohibé (sauf rares exceptions) : il fragilise durablement la relation de confiance.</div>","frequence":0},{"id":"1-7","rang":"A","rubrique":"Définition","titre":"Connaître la notion d’ajustement au stress","contenu":"<p>L'<strong><span class=\"kw-def\">ajustement au stress</span></strong> regroupe <span class=\"kw-clinique\">les</span> <strong>efforts cognitifs, émotionnels et comportementaux</strong> déployés par un individu pour s'adapter au stress de la maladie (= <strong><span class=\"kw-def\">compétences d'adaptation</span></strong> ou <strong><span class=\"kw-def\">coping</span></strong>). Il s'inscrit dans un <strong><span class=\"kw-def\">processus de transaction</span></strong> (d'après Bruchon-Schweitzer et Boujut) entre l'individu et la situation.</p>\n\n<h4 class=\"kw-def\">Phase d'évaluation</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Évaluation primaire</span></strong> = <strong><span class=\"kw-clinique\">stress perçu</span></strong> : perception de la situation (<span class=\"kw-alerte\">menace</span>, défi, opportunité).</li>\n  <li><strong><span class=\"kw-def\">Évaluation secondaire</span></strong> = <strong><span class=\"kw-clinique\">contrôle perçu</span></strong> (ressources personnelles, capacité à contrôler la situation) et <strong><span class=\"kw-clinique\">soutien social perçu</span></strong> (aides et valorisations relationnelles disponibles).</li>\n</ul>\n<div class=\"callout callout-info\">Contrôle perçu et soutien social perçu sont des <strong><span class=\"kw-def\">prédicteurs positifs</span></strong> de l'état de santé ultérieur : ils <strong>facilitent <span class=\"kw-clinique\">les</span> changements de style de vie</strong>. À l'inverse, le <span class=\"kw-alerte\">sentiment de perte de contrôle</span> et l'<span class=\"kw-alerte\">absence de soutien social</span> sont délétères.</div>\n\n<h4 class=\"kw-def\">Phase d'ajustement (coping)</h4>\n<p>Processus interposé entre l'individu et la situation stressante pour en <strong>réduire l'impact</strong> ; il dépend de l'évaluation précédente :</p>\n<ul>\n  <li><strong><span class=\"kw-def\">Stratégies centrées sur le problème</span></strong> : adoptées si le patient <strong>pense pouvoir agir</strong> sur sa situation de maladie.</li>\n  <li><strong><span class=\"kw-def\">Stratégies centrées sur l'émotion</span></strong> : adoptées s'il <strong>pense ne rien pouvoir y changer</strong> — il cherche alors à « se modifier lui-même » pour supporter la situation.</li>\n</ul>\n<p>Ces évaluations sont influencées par des facteurs <strong><span class=\"kw-def\">bio-psycho-sociaux</span></strong> et par la <strong><span class=\"kw-def\">théorie profane</span></strong> : attribuer <span class=\"kw-clinique\">les</span> événements à des facteurs <span class=\"kw-etio\">externes non maîtrisables</span> → <span class=\"kw-clinique\">contrôle perçu faible</span> ; les attribuer à ses <span class=\"kw-etio\">aptitudes personnelles</span> → <span class=\"kw-clinique\">contrôle perçu fort</span>.</p>\n\n<div class=\"callout callout-warn\">⚠️ Ne pas confondre <strong>ajustement au stress</strong> (conscient, lié au <span class=\"kw-clinique\">jugement</span> et à la délibération) et <strong>mécanismes de défense</strong> (processus <span class=\"kw-clinique\">inconscients</span> automatiques).</div>","frequence":0},{"id":"1-8","rang":"A","rubrique":"Définition","titre":"Connaître les principaux mécanismes de défense observés chez les patients / leurs proches / les professionnels de santé dans le cadre de l’annonce d’une mauvaise nouvelle en santé","contenu":"<p>Un <strong><span class=\"kw-def\">mécanisme de défense</span></strong> est une <strong>réaction psychologique inconsciente</strong> visant à gérer le <span class=\"kw-clinique\">stress</span> lié à la maladie. Il est à distinguer du <strong>processus d'ajustement</strong> (conscient, lié au jugement). On l'observe chez le <strong>patient</strong>, ses <strong>proches</strong> et <span class=\"kw-clinique\">les</span> <strong>professionnels de santé</strong>, notamment lors de l'<span class=\"kw-def\">annonce</span> d'une <span class=\"kw-alerte\">mauvaise nouvelle</span>.</p>\n\n<h4 class=\"kw-def\">Chez le patient — acceptation de la mauvaise nouvelle</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Déni</span></strong> : maintient hors de la conscience <span class=\"kw-clinique\">les</span> pensées et affects liés à la maladie.</li>\n  <li><strong><span class=\"kw-def\">Dénégation</span></strong> : refus <strong>partiel</strong> de la réalité.</li>\n  <li><strong><span class=\"kw-def\">Colère</span></strong> : angoisse et sentiment d'injustice → <span class=\"kw-clinique\">agressivité</span> envers soignants et entourage.</li>\n  <li><strong><span class=\"kw-def\">Négociation</span></strong> : marchandages pour <strong>reprendre le contrôle</strong> de la situation.</li>\n  <li><strong><span class=\"kw-def\">Dépression</span></strong> : perte douloureuse de l'<span class=\"kw-clinique\">identité</span> et du <span class=\"kw-clinique\">projet de vie</span> antérieurs.</li>\n  <li><strong><span class=\"kw-def\">Acceptation</span></strong> : reconstruction de l'identité en intégrant la mauvaise nouvelle.</li>\n</ul>\n\n<h4 class=\"kw-def\">Chez le patient — adaptation à la mauvaise nouvelle</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Isolation</span></strong> : sépare pensées et affects (<span class=\"kw-clinique\">détachement froid</span>) → rationalisation biomédicale.</li>\n  <li><strong><span class=\"kw-def\">Déplacement</span></strong> : détourne l'affect sur un <span class=\"kw-clinique\">objet futile</span> (ex. nourriture à l'hôpital).</li>\n  <li><strong><span class=\"kw-def\">Projection</span></strong> : attribue à autrui ses propres affects (ex. impute l'échec à l'incompétence supposée du médecin).</li>\n  <li><strong><span class=\"kw-def\">Sublimation / combativité</span></strong> : défense <strong>positive</strong> → investissement dans un projet personnel.</li>\n  <li><strong><span class=\"kw-def\">Régression</span></strong> : <span class=\"kw-alerte\">dépendance disproportionnée</span> envers l'entourage.</li>\n  <li><strong><span class=\"kw-def\">Maîtrise</span></strong> : tente de tout contrôler → <span class=\"kw-clinique\">attitudes obsessionnelles</span> et fortes exigences.</li>\n</ul>\n\n<h4 class=\"kw-def\">Chez le médecin et <span class=\"kw-clinique\">les</span> soignants</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Mensonge</span></strong> (par omission) : pour se préserver lui-même → <span class=\"kw-alerte\">effets délétères, à prohiber</span>.</li>\n  <li><strong><span class=\"kw-def\">Identification projective</span></strong> : attribue au patient ses propres représentations pour <strong>éviter une discussion pénible</strong>.</li>\n  <li><strong><span class=\"kw-def\">Rationalisation</span></strong> : se réfugie derrière un discours <span class=\"kw-clinique\">technoscientifique</span> hermétique.</li>\n  <li><strong><span class=\"kw-def\">Fausse réassurance</span></strong> : entretient un <span class=\"kw-alerte\">espoir disproportionné</span>.</li>\n  <li><strong><span class=\"kw-def\">Fuite en avant</span></strong> : délivre l'information « à marche forcée » pour s'en débarrasser.</li>\n</ul>","frequence":2},{"id":"1-9","rang":"A","rubrique":"Définition","titre":"Connaître la notion d’empathie clinique","contenu":"<p>L'<strong><span class=\"kw-def\">empathie clinique</span></strong> est la capacité de <strong>comprendre <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">affects</span> et les <span class=\"kw-clinique\">pensées</span> d'autrui</strong>, puis de <strong>lui faire comprendre qu'il est compris</strong>. Elle articule quatre dimensions complémentaires :</p>\n<ul>\n  <li><strong><span class=\"kw-def\">Empathie affective</span></strong> et <strong><span class=\"kw-def\">cognitive</span></strong> : <span class=\"kw-clinique\">comprendre</span> <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">affects</span> et les <span class=\"kw-clinique\">pensées</span> du patient.</li>\n  <li><strong><span class=\"kw-def\">Empathie motivationnelle</span></strong> et <strong><span class=\"kw-def\">comportementale</span></strong> : <strong>manifester</strong> au patient qu'il est <span class=\"kw-clinique\">compris</span>.</li>\n</ul>\n\n<div class=\"callout callout-warn\">⚠️ <strong>Ne pas confondre trois notions :</strong>\n<ul>\n  <li><strong><span class=\"kw-def\">Empathie</span></strong> : <span class=\"kw-clinique\">comprendre</span> l'autre sans se substituer à lui.</li>\n  <li><strong><span class=\"kw-def\">Sympathie</span></strong> : <span class=\"kw-clinique\">ressentir la même chose</span> qu'autrui (« je serais inquiet moi aussi ! »).</li>\n  <li><strong><span class=\"kw-def\">Apathie</span></strong> : <span class=\"kw-alerte\">incapacité</span> à ressentir ou reconnaître l'émotion d'autrui (« vous n'avez pas de raison d'être inquiet »).</li>\n</ul>\n</div>\n\n<h4 class=\"kw-def\">Bénéfices cliniques de l'empathie</h4>\n<ul>\n  <li>Améliore la <strong><span class=\"kw-clinique\">communication</span></strong> médecin-patient.</li>\n  <li>Favorise l'<strong><span class=\"kw-clinique\">adhésion thérapeutique</span></strong>.</li>\n  <li>Réduit l'<span class=\"kw-clinique\">anxiété</span> et le <span class=\"kw-clinique\">stress</span> du patient.</li>\n  <li><strong>Humanise</strong> la relation de soin.</li>\n</ul>\n\n<p>L'empathie ne consiste pas seulement à <strong>écouter</strong>, mais à <strong>montrer au patient qu'il est compris</strong>.</p>","frequence":0},{"id":"1-10","rang":"A","rubrique":"Définition","titre":"Connaître la notion d’alliance thérapeutique","contenu":"<p>L'<strong><span class=\"kw-def\">alliance thérapeutique</span></strong> est le <strong>résultat du processus d'engagement</strong> : une <strong><span class=\"kw-clinique\">relation de confiance</span></strong> permettant au patient de raconter son problème de santé. Le <strong><span class=\"kw-def\">consentement</span></strong> est essentiel à obtenir, et l'alliance est <strong>à rechercher y compris dans le cadre des soins sans consentement</strong>.</p>\n\n<h4 class=\"kw-def\">Trois composantes</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Buts</span></strong> : accord sur <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">objectifs</span> de la thérapie.</li>\n  <li><strong><span class=\"kw-def\">Tâches</span></strong> : accord sur <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">moyens</span> à mettre en œuvre pour les atteindre.</li>\n  <li><strong><span class=\"kw-def\">Qualité du lien</span></strong> : <span class=\"kw-clinique\">confiance</span> et <span class=\"kw-clinique\">estime mutuelle</span> entre le médecin et le malade.</li>\n</ul>\n\n<h4 class=\"kw-def\">Signes d'alliance verbaux</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Durée de l'énoncé</span></strong> : alliance <span class=\"kw-alerte\">faible</span> si <span class=\"kw-clinique\">réponse brève</span>.</li>\n  <li><strong><span class=\"kw-def\">Temps de latence</span></strong> à l'énoncé : alliance faible si la <span class=\"kw-clinique\">latence est courte</span>.</li>\n  <li><strong><span class=\"kw-def\">Pourcentage d'interruption</span></strong> : alliance faible si le patient a tendance à <span class=\"kw-clinique\">interrompre</span> le médecin.</li>\n</ul>\n\n<h4 class=\"kw-def\">Signes d'alliance non verbaux</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Proxémique</span></strong> : <span class=\"kw-clinique\">distance</span> et orientation des interlocuteurs.</li>\n  <li><strong><span class=\"kw-def\">Gestuelle</span></strong> : ensemble des <span class=\"kw-clinique\">attitudes</span> du médecin et du patient.</li>\n  <li><strong><span class=\"kw-def\">Paralangage</span></strong> : <span class=\"kw-clinique\">timbre</span>, <span class=\"kw-clinique\">intensité</span>, <span class=\"kw-clinique\">prosodie</span>.</li>\n  <li><strong><span class=\"kw-def\">Expressions émotionnelles</span></strong> : états affectifs manifestés et vécus.</li>\n</ul>\n\n<div class=\"callout callout-info\">La décision thérapeutique naît de la confrontation entre la <strong><span class=\"kw-def\">théorie savante</span></strong> du médecin (preuves) et la <strong><span class=\"kw-def\">théorie profane</span></strong> du patient — d'où l'importance d'une alliance solide.</div>","frequence":0},{"id":"1-11","rang":"A","rubrique":"Définition","titre":"Connaître les principales étapes du processus de changement","contenu":"<p>Le <strong><span class=\"kw-def\">processus de changement</span></strong> d'un <span class=\"kw-def\">« comportement problème »</span> suit un <strong>modèle cyclique</strong> en plusieurs étapes (<strong><span class=\"kw-def\">modèle transthéorique</span></strong> de <strong>Prochaska et DiClemente</strong>). Le patient peut <strong>repasser plusieurs fois</strong> par le cycle avant d'en sortir définitivement.</p>\n\n<table >\n  <thead><tr><th>Étape</th><th>Positionnement du patient</th></tr></thead>\n  <tbody>\n    <tr>\n      <td><strong><span class=\"kw-def\">1. Pré-contemplation</span></strong></td>\n      <td>Le changement a <strong>moins d'avantages que d'inconvénients</strong> ; pas de <span class=\"kw-clinique\">conscience du problème</span> — <em>« je bois et alors ? »</em></td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">2. Contemplation</span></strong></td>\n      <td><span class=\"kw-clinique\">Ambivalence</span> : avantages et inconvénients perçus comme équivalents — <em>« il faudrait peut-être que j'arrête »</em></td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">3. Détermination</span></strong></td>\n      <td>Inconvénients &gt; avantages ; <strong>décision</strong> et <span class=\"kw-clinique\">plan d'action</span> — <em>« la semaine prochaine j'arrête »</em></td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">4. Action</span></strong></td>\n      <td>Engagement actif ; <span class=\"kw-clinique\">efficacité personnelle</span> ressentie ; mise en place du changement</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">5. Maintien</span></strong></td>\n      <td>Comportement <strong>consolidé</strong> dans la durée ; <span class=\"kw-alerte\">risque de rechute</span> encore présent</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">6. Rechute</span></strong> (optionnelle)</td>\n      <td>Retour temporaire à l'ancien comportement ; <strong>peut relancer le cycle</strong> avec une meilleure compréhension</td>\n    </tr>\n  </tbody>\n</table>\n\n<div class=\"callout callout-info\">La <strong>sortie définitive</strong> survient quand le nouveau comportement est <strong><span class=\"kw-clinique\">intégré et stable</span></strong>. Ce modèle est utilisé en <span class=\"kw-etio\">addictologie</span>, <span class=\"kw-etio\">nutrition</span> et <span class=\"kw-etio\">activité physique</span> : la <strong>rechute fait partie du processus</strong>, ce n'est pas un échec.</div>","frequence":1},{"id":"1-12","rang":"A","rubrique":"Définition","titre":"Connaître les indications et principes de l’entretien motivationnel","contenu":"<p>L'<strong><span class=\"kw-def\">entretien motivationnel</span></strong> est un <strong>style d'entretien participatif</strong> visant à <strong>résoudre l'<span class=\"kw-clinique\">ambivalence</span></strong> du patient et à réveiller une <strong><span class=\"kw-def\">motivation intrinsèque</span></strong> (propre, libre) vers le changement.</p>\n\n<h4 class=\"kw-def\">Concepts clés</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Motivation</span></strong> : non pas un trait de caractère immuable, mais un <strong>état fluctuant</strong>, fonction des représentations, du sentiment d'efficacité et de la qualité de l'entretien.</li>\n  <li><strong><span class=\"kw-def\">Ambivalence</span></strong> : statu quo entre rester dans le <span class=\"kw-clinique\">comportement problème</span> (qui semble avoir plus d'avantages) et changer.</li>\n</ul>\n\n<div class=\"callout callout-warn\">⚠️ L'entretien motivationnel <strong>ne consiste pas à convaincre</strong> le patient : l'objectif <span class=\"kw-ci\">n'est pas d'induire une motivation extrinsèque</span> par l'argumentation du thérapeute.</div>\n\n<h4 class=\"kw-def\">Indications</h4>\n<p>Appliqué initialement aux <strong><span class=\"kw-etio\">conduites addictives</span></strong>, il s'étend à <strong>tout comportement problème</strong> (nutrition, observance, mode de vie).</p>\n\n<h4 class=\"kw-def\">Principes — mnémotechnique VICTOIRE</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">V</span>aloriser</strong> toute action en faveur du changement (renforce le sentiment d'efficacité).</li>\n  <li><strong><span class=\"kw-def\">I</span>ntéresser</strong> le patient à la question du changement et à son ambivalence.</li>\n  <li><strong><span class=\"kw-def\">C</span>omprendre</strong> le patient (démarche <span class=\"kw-clinique\">empathique</span>).</li>\n  <li><strong><span class=\"kw-def\">T</span>olérer</strong> <span class=\"kw-clinique\">les</span> résistances, avec un <strong>jugement positif inconditionnel</strong>.</li>\n  <li><strong><span class=\"kw-def\">O</span>uvrir</strong> par des <span class=\"kw-clinique\">questions ouvertes</span>.</li>\n  <li><strong><span class=\"kw-def\">I</span>nsister</strong> sur l'ambivalence, <span class=\"kw-ci\">sans prendre parti contre</span> <span class=\"kw-clinique\">les</span> représentations du patient.</li>\n  <li><strong><span class=\"kw-def\">R</span>eformuler</strong> le discours du patient (démarche empathique).</li>\n  <li><strong><span class=\"kw-def\">É</span>couter</strong> ses propres représentations.</li>\n</ul>\n\n<div class=\"callout callout-info\">En cas de retour en arrière : <strong>ne pas induire de <span class=\"kw-alerte\">sentiment d'échec</span></strong>, reprendre l'entretien sur <span class=\"kw-clinique\">les</span> raisons de l'arrêt et chercher de <strong>nouvelles stratégies</strong>.</div>","frequence":1},{"id":"1-13","rang":"A","rubrique":"Prise en charge","titre":"Savoir comment se montrer empathique à l’égard du patient","contenu":"<p>Se montrer empathique repose sur un <strong><span class=\"kw-def\">processus en 5 étapes</span></strong> qui transforme l'émotion perçue chez le patient en un sentiment, pour lui, d'<strong>être compris</strong>.</p>\n\n<h4 class=\"kw-def\"><span class=\"kw-clinique\">Les</span> 5 étapes du processus d'empathie</h4>\n<ul>\n  <li><strong>1. <span class=\"kw-def\">Expression</span></strong> : le patient exprime une <span class=\"kw-clinique\">émotion</span>, une préoccupation (« je suis très inquiet… »).</li>\n  <li><strong>2. <span class=\"kw-def\">Reconnaissance</span></strong> : le médecin <strong>identifie et comprend</strong> l'émotion, se met à sa place.</li>\n  <li><strong>3. <span class=\"kw-def\">Transmission</span></strong> : le médecin <strong><span class=\"kw-clinique\">verbalise</span></strong> sa compréhension (« je comprends que cette situation soit stressante »).</li>\n  <li><strong>4. <span class=\"kw-def\">Réception</span></strong> : le patient perçoit qu'il est <span class=\"kw-clinique\">compris</span>.</li>\n  <li><strong>5. <span class=\"kw-def\">Réaction en retour</span></strong> : le patient ressent un <span class=\"kw-clinique\">apaisement</span> → <strong>renforcement de la confiance</strong>.</li>\n</ul>\n\n<h4 class=\"kw-def\">En pratique</h4>\n<ul>\n  <li><strong>Accueillir</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">manifestations affectives</span> sans les juger.</li>\n  <li><strong>Nommer l'émotion</strong> perçue pour montrer qu'elle est reconnue.</li>\n  <li><strong><span class=\"kw-def\">Reformuler</span></strong> et <strong><span class=\"kw-def\">écouter</span></strong> activement le discours du patient.</li>\n  <li>Soigner la communication <strong>non verbale</strong> : <span class=\"kw-clinique\">proxémique</span>, <span class=\"kw-clinique\">gestuelle</span>, <span class=\"kw-clinique\">paralangage</span>.</li>\n</ul>\n\n<div class=\"callout callout-info\">L'empathie ne se limite pas à écouter : il faut <strong>montrer activement au patient qu'il est compris</strong>. Bénéfices : meilleure <span class=\"kw-clinique\">adhésion thérapeutique</span>, <span class=\"kw-clinique\">anxiété</span> réduite, relation de soin humanisée.</div>","frequence":0},{"id":"1-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d’une communication adaptée, verbale et non verbale, avec le patient et son entourage","contenu":"<p>Une <strong><span class=\"kw-def\">communication adaptée</span></strong> avec le patient et son entourage combine un registre <strong>verbal</strong> et un registre <strong>non verbal</strong>, tous deux porteurs de sens dans la relation de soin.</p>\n\n<h4 class=\"kw-def\">Communication verbale</h4>\n<ul>\n  <li>Vocabulaire <strong>approprié</strong>, <span class=\"kw-ci\">sans jargon ni euphémisme</span>.</li>\n  <li>Privilégier <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-def\">questions ouvertes</span></strong> (le patient ne répond pas par oui ou non).</li>\n  <li>Information <strong><span class=\"kw-clinique\">progressive</span></strong>, au rythme du patient.</li>\n  <li>Faire <strong><span class=\"kw-def\">reformuler</span></strong> le patient pour vérifier la <span class=\"kw-clinique\">compréhension</span>.</li>\n</ul>\n<p>Des marqueurs verbaux renseignent sur la <strong><span class=\"kw-def\">qualité de l'alliance</span></strong> : <span class=\"kw-clinique\">durée de l'énoncé</span>, <span class=\"kw-clinique\">temps de latence</span> et <span class=\"kw-clinique\">pourcentage d'interruption</span> du patient.</p>\n\n<h4 class=\"kw-def\">Communication non verbale</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Proxémique</span></strong> : <span class=\"kw-clinique\">distance</span> et orientation des interlocuteurs.</li>\n  <li><strong><span class=\"kw-def\">Gestuelle</span></strong> : ensemble des <span class=\"kw-clinique\">attitudes</span> du médecin et du patient.</li>\n  <li><strong><span class=\"kw-def\">Paralangage</span></strong> : <span class=\"kw-clinique\">timbre</span>, <span class=\"kw-clinique\">intensité</span>, <span class=\"kw-clinique\">prosodie</span> de la voix.</li>\n  <li><strong><span class=\"kw-def\">Expressions émotionnelles</span></strong> : états affectifs manifestés et vécus.</li>\n</ul>\n\n<div class=\"callout callout-info\">Le non-verbal traduit l'<strong>investissement affectif</strong> de la relation : il doit rester <strong>cohérent</strong> avec le discours verbal pour entretenir la <span class=\"kw-clinique\">confiance</span>.</div>","frequence":0},{"id":"1-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les enjeux et les modalités de l’annonce d’une mauvaise nouvelle en santé o","contenu":"<p>L'<strong><span class=\"kw-def\">annonce d'une mauvaise nouvelle</span></strong> <strong>ne s'improvise pas</strong> : c'est un acte à fort <strong>enjeu relationnel</strong> qui conditionne la suite de la prise en charge et l'<span class=\"kw-clinique\">alliance thérapeutique</span>. Elle suit une succession d'<strong>étapes structurées</strong>.</p>\n\n<table >\n  <thead><tr><th>Étape</th><th>Contenu</th></tr></thead>\n  <tbody>\n    <tr>\n      <td><strong>1. <span class=\"kw-def\">Temps et espace</span></strong></td>\n      <td>Lieu <span class=\"kw-clinique\">calme</span> garantissant <strong>confidentialité</strong> et intimité ; temps suffisant sans interruption ; proche présent si souhaité.</td>\n    </tr>\n    <tr>\n      <td><strong>2. <span class=\"kw-def\">Quoi annoncer ?</span></strong></td>\n      <td>Questionnement <strong>ouvert</strong> pour distinguer ce que le patient <span class=\"kw-clinique\">sait déjà</span>, <span class=\"kw-clinique\">souhaite savoir</span> et <span class=\"kw-clinique\">doit savoir</span>.</td>\n    </tr>\n    <tr>\n      <td><strong>3. <span class=\"kw-def\">Comment annoncer ?</span></strong></td>\n      <td>Information <strong><span class=\"kw-clinique\">progressive</span></strong>, au rythme du patient ; <span class=\"kw-ci\">sans jargon ni euphémisme</span>.</td>\n    </tr>\n    <tr>\n      <td><strong>4. <span class=\"kw-def\">Vérifier la compréhension</span></strong></td>\n      <td><strong><span class=\"kw-clinique\">Reformulation</span></strong> par le patient (dépend de sa théorie profane et de ses mécanismes de défense).</td>\n    </tr>\n    <tr>\n      <td><strong>5. <span class=\"kw-def\">Démarche empathique</span></strong></td>\n      <td>Accueillir <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">manifestations affectives</span> du patient.</td>\n    </tr>\n    <tr>\n      <td><strong>6. <span class=\"kw-def\">Espoir réaliste</span></strong></td>\n      <td>Permettre au patient de se <strong>projeter</strong> ; planifier le <span class=\"kw-clinique\">suivi</span> pour réduire l'incertitude des étapes à venir.</td>\n    </tr>\n    <tr>\n      <td><strong>7. <span class=\"kw-def\">Support écrit</span></strong></td>\n      <td>Résumer l'information — <strong>en <span class=\"kw-bio\">complément</span></strong>, jamais en remplacement des étapes précédentes.</td>\n    </tr>\n  </tbody>\n</table>\n\n<div class=\"callout callout-danger\">⚠️ <strong>Ne JAMAIS faire une <span class=\"kw-def\">annonce</span> au <span class=\"kw-alerte\">téléphone</span>.</strong> Neutraliser le téléphone et signaler de ne pas déranger pendant l'entretien.</div>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"13d60129550d","n":1,"o":"1-1","u":"Définition","t":"Connaître la définition de la relation médecin-malade","q":"Quelle est la définition de la relation médecin-malade ?","a":"<p>La relation médecin-malade est une relation <strong>interpersonnelle</strong> qui implique plusieurs acteurs (médecin, soignants, patient, entourage) et se noue autour de la maladie. Elle est caractérisée par des <strong>attentes mutuelles</strong>, un <strong>investissement affectif</strong> et se déroule dans un cadre <strong>socioculturel et éthique</strong>.</p>"},{"i":"40dd35d4302c","n":1,"o":"1-1","u":"Définition","t":"Connaître la définition de la relation médecin-malade","q":"Quels sont les cinq axes de l'asymétrie dans la relation médecin-malade ?","a":"<ul><li>La <strong>représentation de la maladie</strong> (expertise du vécu pour le patient vs. savoir scientifique pour le médecin).</li><li>La <strong>représentation de la santé</strong> (moyen pour la qualité de vie pour le patient vs. absence de maladie pour le médecin).</li><li>La <strong>position</strong> (faiblesse/vulnérabilité pour le patient vs. force/maîtrise du savoir pour le médecin).</li><li>Les <strong>peurs</strong> (maladie, handicap, mort pour le patient vs. échec, erreur, annonce de maladie grave pour le médecin).</li><li>Les <strong>attentes</strong> (savoir, guérison, reconnaissance de la détresse pour le patient vs. reconnaissance professionnelle, acceptation des décisions pour le médecin).</li></ul>"},{"i":"849b36568fe8","n":1,"o":"1-1","u":"Définition","t":"Connaître la définition de la relation médecin-malade","q":"Quel est le trait fondamental de la relation médecin-malade ?","a":"<p>Le trait fondamental de la relation médecin-malade est qu'elle est par nature <strong>asymétrique</strong>. Le médecin et le malade diffèrent sur plusieurs plans, et comprendre cette asymétrie est essentiel pour une prise en charge de qualité.</p>"},{"i":"05a429b3c59a","n":1,"o":"1-10","u":"Définition","t":"Connaître la notion d’alliance thérapeutique","q":"Quelles sont les trois composantes essentielles de l'alliance thérapeutique ?","a":"<ul><li><strong>Buts</strong> : un accord mutuel sur les objectifs de la thérapie.</li><li><strong>Tâches</strong> : un accord sur les moyens et les actions à mettre en œuvre pour atteindre ces objectifs.</li><li><strong>Qualité du lien</strong> : une confiance et une estime mutuelle entre le médecin et le patient.</li></ul>"},{"i":"22f1b83b7a89","n":1,"o":"1-10","u":"Définition","t":"Connaître la notion d’alliance thérapeutique","q":"Quels sont les signes non verbaux de l'alliance thérapeutique ?","a":"<ul><li>La <strong>proxémique</strong> : la distance et l'orientation des interlocuteurs.</li><li>La <strong>gestuelle</strong> : l'ensemble des attitudes du médecin et du patient.</li><li>Le <strong>paralangage</strong> : le timbre, l'intensité et la prosodie de la voix.</li><li>Les <strong>expressions émotionnelles</strong> : les états affectifs manifestés et vécus.</li></ul>"},{"i":"67ea290004b7","n":1,"o":"1-10","u":"Définition","t":"Connaître la notion d’alliance thérapeutique","q":"Quels sont les signes verbaux d'une alliance thérapeutique faible ?","a":"<ul><li>Une <strong>durée d'énoncé brève</strong> de la part du patient.</li><li>Un <strong>temps de latence court</strong> avant que le patient ne réponde.</li><li>Un <strong>pourcentage élevé d'interruption</strong> du médecin par le patient.</li></ul>"},{"i":"c4104de9405c","n":1,"o":"1-10","u":"Définition","t":"Connaître la notion d’alliance thérapeutique","q":"Qu'est-ce que l'alliance thérapeutique ?","a":"<p>L'alliance thérapeutique est une <strong>relation de confiance</strong> entre le médecin et le patient, qui permet à ce dernier de s'engager dans le soin et de raconter son problème de santé. Elle est le résultat d'un processus d'engagement et doit être recherchée même dans les <strong>soins sans consentement</strong>.</p>"},{"i":"04662c177402","n":1,"o":"1-11","u":"Définition","t":"Connaître les principales étapes du processus de changement","q":"Quel modèle théorique décrit les principales étapes du processus de changement de comportement chez un patient ?","a":"<p>Les principales étapes du processus de changement d'un « comportement problème » sont décrites par le <strong>modèle transthéorique de Prochaska et DiClemente</strong>.</p>"},{"i":"8413aae5d991","n":1,"o":"1-11","u":"Définition","t":"Connaître les principales étapes du processus de changement","q":"Dans quels domaines de la médecine le modèle de Prochaska et DiClemente est-il couramment utilisé pour accompagner le patient ?","a":"<p>Le modèle de Prochaska et DiClemente est couramment utilisé dans des domaines tels que l'<strong>addictologie</strong>, la <strong>nutrition</strong> et l'<strong>activité physique</strong>.</p>"},{"i":"adacc873cd07","n":1,"o":"1-11","u":"Définition","t":"Connaître les principales étapes du processus de changement","q":"Quelles sont les six étapes du processus de changement, selon le modèle de Prochaska et DiClemente ?","a":"<ul><li><strong>Pré-contemplation</strong> : le patient n'a pas conscience du problème, le changement est perçu avec plus d'inconvénients.</li><li><strong>Contemplation</strong> : le patient est ambivalent, avantages et inconvénients du changement sont perçus comme équivalents.</li><li><strong>Détermination</strong> : les inconvénients du comportement problématique l'emportent, le patient prend la décision d'agir et établit un plan.</li><li><strong>Action</strong> : le patient s'engage activement dans le changement et met en place de nouveaux comportements.</li><li><strong>Maintien</strong> : le nouveau comportement est consolidé sur la durée, avec un risque de rechute encore présent.</li><li><strong>Rechute</strong> (optionnelle) : retour temporaire à l'ancien comportement, pouvant relancer le cycle avec une meilleure compréhension.</li></ul>"},{"i":"ee46f146a52d","n":1,"o":"1-11","u":"Définition","t":"Connaître les principales étapes du processus de changement","q":"Pourquoi la rechute, dans le cadre du modèle de Prochaska et DiClemente, n'est-elle pas considérée comme un échec ?","a":"<p>Dans le modèle de Prochaska et DiClemente, la rechute fait <strong>partie intégrante du processus de changement</strong>. Elle n'est pas un échec, mais une étape optionnelle qui peut permettre au patient de relancer le cycle avec une meilleure compréhension de son comportement et des stratégies à adopter.</p>"},{"i":"6d3a782179f1","n":1,"o":"1-12","u":"Définition","t":"Connaître les indications et principes de l’entretien motivationnel","q":"Comment doit-on aborder un éventuel retour en arrière du patient dans le cadre de l'entretien motivationnel ?","a":"<p>En cas de retour en arrière, il ne faut <strong>pas induire de sentiment d'échec</strong> chez le patient. Il convient de <strong>reprendre l'entretien sur les raisons de l'arrêt</strong> et de <strong>chercher de nouvelles stratégies</strong>.</p>"},{"i":"6f269f640d09","n":1,"o":"1-12","u":"Définition","t":"Connaître les indications et principes de l’entretien motivationnel","q":"Dans quelles situations cliniques l'entretien motivationnel trouve-t-il son indication ?","a":"<p>Initialement appliqué aux <strong>conduites addictives</strong>, l'entretien motivationnel s'étend désormais à <strong>tout comportement problème</strong> en santé (ex : troubles de la nutrition, non-observance thérapeutique, modes de vie).</p>"},{"i":"a02cb7031fc5","n":1,"o":"1-12","u":"Définition","t":"Connaître les indications et principes de l’entretien motivationnel","q":"Quelle est la définition de l'entretien motivationnel et son objectif principal ?","a":"<p>L'entretien motivationnel est un <strong>style d'entretien participatif</strong> dont l'objectif est de <strong>résoudre l'ambivalence du patient</strong> et de faire émerger sa <strong>motivation intrinsèque vers le changement</strong>.</p>"},{"i":"da5fdc12be2d","n":1,"o":"1-12","u":"Définition","t":"Connaître les indications et principes de l’entretien motivationnel","q":"Quels sont les principes clés de l'entretien motivationnel, selon la mnémotechnique VICTOIRE ?","a":"<ul><li><strong>V</strong>aloriser toute action en faveur du changement.</li><li><strong>I</strong>ntéresser le patient à la question du changement et à son ambivalence.</li><li><strong>C</strong>omprendre le patient (démarche empathique).</li><li><strong>T</strong>olérer les résistances, avec un jugement positif inconditionnel.</li><li><strong>O</strong>uvrir par des questions ouvertes.</li><li><strong>I</strong>nsister sur l'ambivalence, sans prendre parti contre les représentations du patient.</li><li><strong>R</strong>eformuler le discours du patient (démarche empathique).</li><li><strong>É</strong>couter ses propres représentations.</li></ul>"},{"i":"3b740d08d5a2","n":1,"o":"1-13","u":"Prise en charge","t":"Savoir comment se montrer empathique à l’égard du patient","q":"Dans le processus d'empathie, quelle est l'étape où le médecin verbalise sa compréhension de l'émotion du patient ?","a":"<p>Il s'agit de l'étape de la <strong>transmission</strong> : le médecin verbalise sa compréhension, par exemple en disant « je comprends que cette situation soit stressante ».</p>"},{"i":"51d71cf6ace9","n":1,"o":"1-13","u":"Prise en charge","t":"Savoir comment se montrer empathique à l’égard du patient","q":"Comment peut-on, en pratique, manifester activement son empathie envers un patient ?","a":"<ul><li>Accueillir les manifestations affectives <strong>sans les juger</strong>.</li><li><strong>Nommer l'émotion</strong> perçue.</li><li><strong>Reformuler</strong> et <strong>écouter activement</strong> le discours du patient.</li><li>Soigner la <strong>communication non verbale</strong> (proxémique, gestuelle, paralangage).</li></ul>"},{"i":"b5f8743c188d","n":1,"o":"1-13","u":"Prise en charge","t":"Savoir comment se montrer empathique à l’égard du patient","q":"Selon le modèle en 5 étapes, quelle est la première étape du processus empathique dans la relation médecin-patient ?","a":"<p>La première étape est l'<strong>expression</strong> : le patient exprime une <strong>émotion</strong> ou une préoccupation.</p>"},{"i":"f91de09e07fc","n":1,"o":"1-13","u":"Prise en charge","t":"Savoir comment se montrer empathique à l’égard du patient","q":"Quels sont les bénéfices de l'empathie du médecin pour le patient et le soin ?","a":"<ul><li>Une meilleure <strong>adhésion thérapeutique</strong>.</li><li>Une <strong>anxiété réduite</strong>.</li><li>Une <strong>relation de soin humanisée</strong>.</li></ul>"},{"i":"0ac003b978ce","n":1,"o":"1-14","u":"Prise en charge","t":"Connaître les principes d’une communication adaptée, verbale et non verbale, avec le patient et son entourage","q":"Quels sont les principaux éléments de la communication non verbale à prendre en compte dans la relation médecin-malade ?","a":"<ul><li>La <strong>proxémie</strong> (distance et orientation).</li><li>La <strong>gestuelle</strong> (attitudes du médecin et du patient).</li><li>Le <strong>paralangage</strong> (timbre, intensité, prosodie de la voix).</li><li>Les <strong>expressions émotionnelles</strong> (états affectifs manifestés et vécus).</li></ul>"},{"i":"49b66150ec29","n":1,"o":"1-14","u":"Prise en charge","t":"Connaître les principes d’une communication adaptée, verbale et non verbale, avec le patient et son entourage","q":"Quels sont les principes clés d'une communication verbale adaptée avec le patient ?","a":"<ul><li>Utiliser un <strong>vocabulaire approprié</strong>, sans jargon ni euphémisme.</li><li>Privilégier les <strong>questions ouvertes</strong>.</li><li>Délivrer une <strong>information progressive</strong>, au rythme du patient.</li><li>Faire <strong>reformuler le patient</strong> pour vérifier la compréhension.</li></ul>"},{"i":"a687c02d13cb","n":1,"o":"1-14","u":"Prise en charge","t":"Connaître les principes d’une communication adaptée, verbale et non verbale, avec le patient et son entourage","q":"Pourquoi la communication non verbale doit-elle être cohérente avec le discours verbal dans la relation de soin ?","a":"<p>La cohérence entre le non-verbal et le verbal est essentielle pour entretenir la <strong>confiance</strong> avec le patient, car le non-verbal traduit l'investissement affectif dans la relation.</p>"},{"i":"c4fb7671054b","n":1,"o":"1-14","u":"Prise en charge","t":"Connaître les principes d’une communication adaptée, verbale et non verbale, avec le patient et son entourage","q":"Quels sont les deux registres principaux de communication à adapter avec le patient et son entourage dans la relation de soin ?","a":"<p>Les deux registres principaux sont la <strong>communication verbale</strong> et la <strong>communication non verbale</strong>.</p>"},{"i":"9449fe596620","n":1,"o":"1-15","u":"Prise en charge","t":"Connaître les enjeux et les modalités de l’annonce d’une mauvaise nouvelle en santé o","q":"Quel rôle joue le support écrit dans l'annonce d'une mauvaise nouvelle en santé ?","a":"<p>Un <strong>support écrit</strong> peut <strong>résumer l'information</strong>. Il est un <strong>complément</strong> aux étapes orales, mais <strong>jamais un remplacement</strong>.</p>"},{"i":"aa0aab746657","n":1,"o":"1-15","u":"Prise en charge","t":"Connaître les enjeux et les modalités de l’annonce d’une mauvaise nouvelle en santé o","q":"Quelle est la principale interdiction concernant le mode de communication pour une annonce d'une mauvaise nouvelle ?","a":"<p>Il ne faut <strong>JAMAIS faire une annonce au téléphone</strong>.</p>"},{"i":"be0f8a6b2815","n":1,"o":"1-15","u":"Prise en charge","t":"Connaître les enjeux et les modalités de l’annonce d’une mauvaise nouvelle en santé o","q":"Quelles sont les étapes clés pour préparer le cadre d'une annonce de mauvaise nouvelle en santé ?","a":"<ul><li>Mettre en place un <strong>temps et espace</strong> adaptés : un <strong>lieu calme</strong> garantissant <strong>confidentialité et intimité</strong>, avec un <strong>temps suffisant sans interruption</strong>.</li><li>Proposer la présence d'un <strong>proche</strong> si le patient le souhaite.</li><li><strong>Neutraliser le téléphone</strong> et signaler de ne pas être dérangé pendant l'entretien.</li></ul>"},{"i":"c94f9f4b43d7","n":1,"o":"1-15","u":"Prise en charge","t":"Connaître les enjeux et les modalités de l’annonce d’une mauvaise nouvelle en santé o","q":"Comment doit être menée la discussion lors de l'annonce d'une mauvaise nouvelle en santé ?","a":"<ul><li>Commencer par un <strong>questionnement ouvert</strong> pour distinguer <strong>ce que le patient sait déjà</strong>, <strong>souhaite savoir</strong> et <strong>doit savoir</strong>.</li><li>Délivrer l'information de manière <strong>progressive</strong>, <strong>au rythme du patient</strong>, en évitant le jargon médical et les euphémismes.</li><li>Accueillir les <strong>manifestations affectives</strong> du patient avec une <strong>démarche empathique</strong>.</li><li>Permettre au patient de se projeter en maintenant un <strong>espoir réaliste</strong> et en planifiant le suivi pour réduire l'incertitude.</li></ul>"},{"i":"dac673f57828","n":1,"o":"1-15","u":"Prise en charge","t":"Connaître les enjeux et les modalités de l’annonce d’une mauvaise nouvelle en santé o","q":"Pourquoi l'annonce d'une mauvaise nouvelle en santé ne doit-elle pas être improvisée ?","a":"<p>L'annonce d'une mauvaise nouvelle est un <strong>acte à fort enjeu relationnel</strong> qui conditionne la suite de la prise en charge et l'alliance thérapeutique. Elle doit suivre une <strong>succession d'étapes structurées</strong>.</p>"},{"i":"f2275111b335","n":1,"o":"1-15","u":"Prise en charge","t":"Connaître les enjeux et les modalités de l’annonce d’une mauvaise nouvelle en santé o","q":"Comment s'assurer de la bonne compréhension de l'annonce d'une mauvaise nouvelle par le patient ?","a":"<p>La compréhension doit être vérifiée par une <strong>reformulation par le patient</strong>. Il faut prendre en compte sa <strong>théorie profane</strong> et ses <strong>mécanismes de défense</strong>.</p>"},{"i":"378eac0688a0","n":1,"o":"1-2","u":"Définition","t":"Connaître les principaux déterminants de la relation médecin-malade","q":"Comment les dynamiques de la relation médecin-malade sont-elles traditionnellement classifiées, et quels en sont les déterminants principaux ?","a":"<p>La relation médecin-malade se classe selon :</p><ul><li>Les <strong>quatre types de relation</strong>, basés sur le degré d'<strong>implication du patient</strong>.</li><li>Les <strong>trois modèles de décision</strong>, basés sur les modalités d'<strong>information</strong> et de <strong>prise de décision</strong>.</li></ul><p>Ces classifications décrivent la répartition des rôles (actif/passif) du médecin et du patient, ainsi que le niveau d'implication attendu du malade.</p>"},{"i":"3de861e5359f","n":1,"o":"1-2","u":"Définition","t":"Connaître les principaux déterminants de la relation médecin-malade","q":"Quels sont les trois modèles de décision principaux qui régissent la relation médecin-malade, et dans quelles situations sont-ils indiqués ?","a":"<ul><li>Le modèle <strong>paternaliste</strong> : l'information est unidirectionnelle (médecin → patient), la décision est prise par le médecin seul. Il est indiqué en situation d'<strong>urgence</strong>, ou si le patient est inconscient ou incapable de décider.</li><li>Le modèle de <strong>décision partagée</strong> : l'information est bidirectionnelle (médecin ↔ patient), la décision est prise conjointement par le médecin et le patient. Il est idéal pour les <strong>maladies chroniques</strong> ou quand plusieurs options thérapeutiques existent.</li><li>Le modèle <strong>informatif</strong> : l'information est unidirectionnelle (médecin → patient), la décision est prise par le patient seul. Il concerne les patients experts, très autonomes, ou pour les maladies rares.</li></ul>"},{"i":"72a2bc11bc30","n":1,"o":"1-2","u":"Définition","t":"Connaître les principaux déterminants de la relation médecin-malade","q":"Quels sont les pièges à éviter concernant les modèles de décision extrêmes en relation médecin-malade ?","a":"<ul><li>Le <strong>paternalisme</strong> peut être <strong>infantilisant</strong> et réduire l'<strong>adhésion thérapeutique</strong> du patient.</li><li>Le modèle <strong>informatif</strong> expose à une décision potentiellement <strong>inadaptée</strong> si le patient manque d'informations pertinentes.</li></ul><p>L'idéal est toujours d'<strong>adapter le modèle au contexte clinique et aux préférences individuelles du patient</strong>.</p>"},{"i":"7f4e0c0c531f","n":1,"o":"1-2","u":"Définition","t":"Connaître les principaux déterminants de la relation médecin-malade","q":"Quels sont les quatre types de relation médecin-malade selon l'implication du patient, et dans quels contextes sont-ils adaptés ?","a":"<ul><li>La relation <strong>activité/passivité</strong> : le patient est passif, le médecin agit seul. Elle est adaptée aux <strong>maladies aiguës graves</strong> (ex: acte chirurgical, coma).</li><li>La relation <strong>consensuelle</strong> : le patient accepte et coopère, étant déjà convaincu de la prise en charge (ex: pose d'un plâtre).</li><li>La relation <strong>coopérative</strong> : le médecin doit convaincre le patient de la nécessité du geste et obtenir sa coopération (ex: examen gynécologique, soins dentaires).</li><li>La relation <strong>participative</strong> : le patient est un acteur privilégié de sa guérison (relation « autonomiste »), adaptée aux <strong>maladies chroniques</strong> (ex: changement de mode de vie).</li></ul>"},{"i":"8cecd72a0c57","n":1,"o":"1-3","u":"Définition","t":"Connaître les principaux corrélats cliniques de la relation médecin-malade","q":"Dans le cadre de la relation médecin-malade, qu'est-ce que le transfert ?","a":"<p>Dans la relation médecin-malade, le transfert désigne tout <strong>investissement affectif du patient sur le médecin</strong>. Il est largement inconscient et réactive des modalités relationnelles de l'enfance, influençant la décision et l'observance.</p>"},{"i":"8d525a507e27","n":1,"o":"1-3","u":"Définition","t":"Connaître les principaux corrélats cliniques de la relation médecin-malade","q":"Dans le cadre de la relation médecin-malade, qu'est-ce que le contre-transfert et pourquoi est-il important de le reconnaître ?","a":"<p>Le contre-transfert est l'<strong>investissement affectif du médecin envers le patient</strong>. Il est important de le reconnaître car il conditionne la qualité du lien et la justesse des décisions, notamment face à un patient difficile. Il peut être positif (risque de perte d'objectivité) ou négatif (risque d'attitudes de rejet).</p>"},{"i":"db6e73a307cd","n":1,"o":"1-3","u":"Définition","t":"Connaître les principaux corrélats cliniques de la relation médecin-malade","q":"En relation médecin-malade, quelle est la distinction entre transfert positif et transfert négatif ?","a":"<ul><li>Le <strong>transfert positif</strong> correspond à un sentiment de sympathie et de confiance du patient envers le médecin.</li><li>Le <strong>transfert négatif</strong> se manifeste par un sentiment d'antipathie et de méfiance du patient envers le médecin.</li></ul>"},{"i":"3f73a7941b67","n":1,"o":"1-4","u":"Définition","t":"Connaître les principes de « l’approche centrée sur le patient »","q":"Quelles sont les quatre étapes clés de la mise en œuvre de l'approche centrée sur le patient et de la décision médicale partagée ?","a":"<p>Les 4 étapes clés sont :</p><ul><li>Établir une atmosphère propice à l'échange, où l'opinion du patient est prise en compte.</li><li>Rechercher les <strong>préférences du patient</strong> concernant les différentes options.</li><li>Échanger les informations sur les options (y compris ne pas traiter), les bénéfices et les risques, tout en recueillant les représentations et valeurs du patient.</li><li>Trouver un <strong>accord mutuel</strong> et prendre une décision ensemble.</li></ul>"},{"i":"40a8d24cf2fa","n":1,"o":"1-4","u":"Définition","t":"Connaître les principes de « l’approche centrée sur le patient »","q":"Quels sont les principes fondamentaux de la décision médicale partagée, pilier de l'approche centrée sur le patient ?","a":"<p>Les principes de la décision médicale partagée sont :</p><ul><li>Un <strong>échange bilatéral d'informations</strong>, intégrant les preuves scientifiques et les valeurs/préférences du patient.</li><li>Une <strong>délibération commune</strong> pour aboutir à une décision acceptée d'un commun accord.</li><li>Elle s'inscrit dans un <strong>cadre légal</strong>, notamment la loi du 4 mars 2002, affirmant le droit du patient de prendre, avec le professionnel, les décisions concernant sa santé, et exigeant un <strong>consentement libre et éclairé</strong>, retirable à tout moment.</li></ul>"},{"i":"7b4b3f2d020b","n":1,"o":"1-4","u":"Définition","t":"Connaître les principes de « l’approche centrée sur le patient »","q":"Comment l'approche centrée sur le patient intègre-t-elle la perspective et les ressources du patient ?","a":"<p>L'approche centrée sur le patient intègre sa <strong>perspective</strong> en considérant :</p><ul><li>Ses conceptions culturelles.</li><li>Ses convictions spirituelles.</li><li>Son état de santé ressenti et son attitude envers la maladie.</li><li>Ses priorités de santé.</li></ul><p>Elle prend également en compte ses <strong>ressources</strong> :</p><ul><li>Financières.</li><li>Accès aux soins.</li><li>Cognitives et émotionnelles.</li><li>Soutien socio-familial.</li></ul>"},{"i":"a335e9e1b536","n":1,"o":"1-4","u":"Définition","t":"Connaître les principes de « l’approche centrée sur le patient »","q":"Quel est le rôle des systèmes d'aide à la décision dans l'approche centrée sur le patient ?","a":"<p>Les systèmes d'aide à la décision (tels que documents ou vidéos) <strong>accompagnent</strong> le processus en aidant le patient à révéler ses valeurs. Ils ne remplacent cependant jamais le rôle du médecin et le partage de la décision ne modifie pas la responsabilité médicale.</p>"},{"i":"a45f74f409a5","n":1,"o":"1-4","u":"Définition","t":"Connaître les principes de « l’approche centrée sur le patient »","q":"Qu'est-ce que l'approche centrée sur le patient en médecine ?","a":"<p>L'approche centrée sur le patient est une démarche qui place le <strong>malade au cœur des décisions</strong> qui le concernent. Elle repose sur le principe du respect de la personne et de sa participation active aux choix de santé, notamment à travers le modèle de la décision médicale partagée.</p>"},{"i":"28b8b6b69962","n":1,"o":"1-5","u":"Définition","t":"Connaître la notion de représentation de la maladie","q":"Quelles sont les différences majeures entre la représentation de la maladie du patient et celle du médecin ?","a":"<ul><li>Le <strong>patient</strong> a une vision principalement basée sur l'<strong>expertise du vécu subjectif</strong> de sa maladie et ses représentations profanes (croyances, affects, motivations). Sa santé est perçue comme un moyen au service de sa qualité de vie.</li><li>Le <strong>médecin</strong> a une vision axée sur l'<strong>expertise médicale</strong>, le savoir scientifique et les aspects objectifs, déterminée par les recommandations fondées sur les preuves. Sa santé est perçue comme l'absence de maladie.</li></ul>"},{"i":"38860ed1edf9","n":1,"o":"1-5","u":"Définition","t":"Connaître la notion de représentation de la maladie","q":"Quelle est la définition de la représentation de la maladie dans le contexte de la relation médecin-malade ?","a":"<p>La représentation de la maladie correspond à la manière dont <strong>chaque acteur</strong> (patient, médecin) se forge une idée de la maladie.</p>"},{"i":"3df000a9aa62","n":1,"o":"1-5","u":"Définition","t":"Connaître la notion de représentation de la maladie","q":"Dans le processus d'engagement clinique, quel est l'intérêt d'identifier la théorie profane du patient ?","a":"<p>Identifier la théorie profane du patient (ses représentations, affects, motivations, transfert, mécanismes de défense) est essentiel car cela fait partie intégrante du <strong>processus d'engagement clinique</strong> et de l'<strong>évaluation initiale</strong>. Cette compréhension permet de mieux adapter la communication et la stratégie thérapeutique.</p>"},{"i":"ff44d5a0490c","n":1,"o":"1-5","u":"Définition","t":"Connaître la notion de représentation de la maladie","q":"Quel est l'impact de la théorie profane du patient sur sa prise en charge et la décision thérapeutique ?","a":"<p>La théorie profane du patient (ses représentations, croyances, affects et motivations) <strong>conditionne</strong> ce qu'il comprend et accepte de l'information médicale, ses stratégies d'adaptation (coping) et son <strong>adhésion au traitement</strong>. La décision thérapeutique naît de la <strong>confrontation</strong> entre cette théorie profane et la théorie savante du médecin.</p>"},{"i":"030fdd0bf1e7","n":1,"o":"1-6","u":"Définition","t":"Connaître les facteurs influençant l’information délivrée au patient","q":"Quels sont les quatre grands types de facteurs influençant l'information délivrée au patient dans la relation médecin-malade ?","a":"<p>L'information délivrée au patient est modulée par quatre types principaux de facteurs :</p><ul><li>Les facteurs liés au <strong>médecin</strong>.</li><li>Les facteurs liés au <strong>patient</strong>.</li><li>Les facteurs liés à la <strong>maladie</strong> elle-même.</li><li>Les facteurs liés au <strong>contexte</strong> de la consultation.</li></ul>"},{"i":"039b283d0dcf","n":1,"o":"1-6","u":"Définition","t":"Connaître les facteurs influençant l’information délivrée au patient","q":"Quels mécanismes de défense du médecin peuvent distordre l'information délivrée au patient ?","a":"<p>Certains mécanismes de défense du médecin peuvent altérer la qualité de l'information :</p><ul><li>Le <strong>mensonge</strong> (souvent par omission) : il protège le médecin mais est délétère pour le patient.</li><li>La <strong>rationalisation</strong> : usage d'un discours technoscientifique complexe, rendant l'information incompréhensible.</li><li>La <strong>fausse réassurance</strong> : entretient un espoir non proportionné aux faits.</li><li>La <strong>fuite en avant</strong> : information donnée de manière excessive, sans tenir compte de la capacité du patient à l'assimiler.</li></ul>"},{"i":"22ac0a3a674e","n":1,"o":"1-6","u":"Définition","t":"Connaître les facteurs influençant l’information délivrée au patient","q":"Quelles sont les modalités essentielles pour délivrer une information de qualité au patient ?","a":"<p>Pour une information de qualité, il est crucial de :</p><ul><li>La délivrer <strong>progressivement</strong>, en respectant le rythme du patient.</li><li>Utiliser un <strong>vocabulaire approprié</strong>, sans jargon ni euphémisme.</li><li><strong>Vérifier la compréhension</strong> du patient en lui demandant de reformuler l'information.</li></ul>"},{"i":"72354a70b316","n":1,"o":"1-6","u":"Définition","t":"Connaître les facteurs influençant l’information délivrée au patient","q":"Quels sont les facteurs liés au patient qui influencent la réception de l'information médicale ?","a":"<p>Plusieurs facteurs propres au patient influencent la réception de l'information :</p><ul><li>Ses <strong>connaissances préalables</strong>.</li><li>Ce qu'il <strong>souhaite savoir</strong> et ce qu'il <strong>doit savoir</strong>.</li><li>Ses <strong>représentations</strong> et sa théorie profane de la maladie.</li><li>Ses <strong>réactions affectives</strong> et ses mécanismes de défense (comme le déni ou l'isolation), qui filtrent la compréhension.</li></ul>"},{"i":"142b51f8fac7","n":1,"o":"1-7","u":"Définition","t":"Connaître la notion d’ajustement au stress","q":"Quelle est la différence fondamentale entre l'ajustement au stress et les mécanismes de défense ?","a":"<p>L'<strong>ajustement au stress (coping)</strong> est un processus <strong>conscient</strong>, lié au jugement et à la délibération. À l'inverse, les <strong>mécanismes de défense</strong> sont des processus <strong>inconscients</strong> et automatiques.</p>"},{"i":"81c9f249a46f","n":1,"o":"1-7","u":"Définition","t":"Connaître la notion d’ajustement au stress","q":"Quelles sont les phases du processus d'ajustement au stress et leurs caractéristiques principales ?","a":"<p>Le processus d'ajustement au stress comporte deux phases principales :</p><ul><li>La phase d'<strong>évaluation</strong> : elle comprend l'évaluation primaire (stress perçu comme menace, défi, opportunité) et l'évaluation secondaire (contrôle perçu et soutien social perçu).</li><li>La phase d'<strong>ajustement (coping)</strong> : elle correspond aux stratégies mises en œuvre après l'évaluation pour réduire l'impact de la situation stressante.</li></ul>"},{"i":"85f93e0e0915","n":1,"o":"1-7","u":"Définition","t":"Connaître la notion d’ajustement au stress","q":"Définition de l'ajustement au stress en relation médecin-malade.","a":"<p>L'ajustement au stress, ou <strong>coping</strong>, désigne l'ensemble des efforts <strong>cognitifs</strong>, <strong>émotionnels</strong> et <strong>comportementaux</strong> qu'un individu met en œuvre pour s'adapter au stress lié à la maladie. C'est un processus de transaction entre l'individu et la situation stressante.</p>"},{"i":"9c76665df904","n":1,"o":"1-7","u":"Définition","t":"Connaître la notion d’ajustement au stress","q":"Quelles sont les deux principales catégories de stratégies d'ajustement au stress (coping) ?","a":"<p>Les deux principales catégories de stratégies d'ajustement au stress sont :</p><ul><li>Les <strong>stratégies centrées sur le problème</strong> : adoptées lorsque le patient estime pouvoir agir sur sa situation de maladie.</li><li>Les <strong>stratégies centrées sur l'émotion</strong> : adoptées lorsque le patient pense ne rien pouvoir changer à la situation, et cherche à se modifier lui-même pour la supporter.</li></ul>"},{"i":"84b0cbf03778","n":1,"o":"1-8","u":"Définition","t":"Connaître les principaux mécanismes de défense observés chez les patients / leurs proches / les professionnels de santé dans le cadre de l’annonce d’une mauvaise nouvelle en santé","q":"Quels sont les mécanismes de défense et d'adaptation plus spécifiques observés chez les patients face à l'annonce d'une mauvaise nouvelle en santé ?","a":"<ul><li><strong>Isolation</strong> : sépare les pensées des affects, entraînant un détachement froid et une rationalisation biomédicale.</li><li><strong>Déplacement</strong> : l'affect est détourné sur un objet futile.</li><li><strong>Projection</strong> : le patient attribue à autrui ses propres affects ou responsabilités.</li><li><strong>Sublimation / combativité</strong> : défense positive avec investissement dans un projet personnel.</li><li><strong>Régression</strong> : dépendance disproportionnée envers l'entourage.</li><li><strong>Maîtrise</strong> : tentative de tout contrôler, se manifestant par des attitudes obsessionnelles et de fortes exigences.</li></ul>"},{"i":"b92fd218bb04","n":1,"o":"1-8","u":"Définition","t":"Connaître les principaux mécanismes de défense observés chez les patients / leurs proches / les professionnels de santé dans le cadre de l’annonce d’une mauvaise nouvelle en santé","q":"Qu'est-ce qu'un mécanisme de défense en psychologie et en quoi se distingue-t-il d'un processus d'ajustement dans le contexte d'une mauvaise nouvelle en santé ?","a":"<p>Un mécanisme de défense est une <strong>réaction psychologique inconsciente</strong> qui vise à gérer le stress lié à la maladie. Il se distingue d'un processus d'ajustement qui est, lui, <strong>conscient</strong> et lié au jugement.</p>"},{"i":"d18b3a6094e5","n":1,"o":"1-8","u":"Définition","t":"Connaître les principaux mécanismes de défense observés chez les patients / leurs proches / les professionnels de santé dans le cadre de l’annonce d’une mauvaise nouvelle en santé","q":"Quels sont les mécanismes de défense psychologiques classiques observés chez les patients face à l'annonce d'une mauvaise nouvelle en santé, concernant l'acceptation de cette nouvelle ?","a":"<ul><li><strong>Déni</strong> : maintient hors de la conscience les pensées et affects douloureux liés à la maladie.</li><li><strong>Dénégation</strong> : refus partiel de la réalité de la maladie.</li><li><strong>Colère</strong> : angoisse et sentiment d'injustice pouvant mener à l'agressivité envers les soignants ou l'entourage.</li><li><strong>Négociation</strong> : tentatives de marchandage pour reprendre le contrôle de la situation.</li><li><strong>Dépression</strong> : perte douloureuse de l'identité et du projet de vie antérieurs.</li><li><strong>Acceptation</strong> : reconstruction de l'identité en intégrant la mauvaise nouvelle.</li></ul>"},{"i":"e8d69613c286","n":1,"o":"1-8","u":"Définition","t":"Connaître les principaux mécanismes de défense observés chez les patients / leurs proches / les professionnels de santé dans le cadre de l’annonce d’une mauvaise nouvelle en santé","q":"Quels sont les mécanismes de défense que l'on peut observer chez le médecin ou les soignants lors de l'annonce d'une mauvaise nouvelle en santé ?","a":"<ul><li><strong>Mensonge (par omission)</strong> : attitude à prohiber, visant à se préserver mais avec des effets délétères pour le patient.</li><li><strong>Identification projective</strong> : attribuer au patient ses propres représentations pour éviter une discussion difficile.</li><li><strong>Rationalisation</strong> : se réfugier derrière un discours technoscientifique complexe pour éviter l'émotion.</li><li><strong>Fausse réassurance</strong> : entretenir un espoir disproportionné chez le patient.</li><li><strong>Fuite en avant</strong> : délivrer l'information rapidement et \"à marche forcée\" pour s'en débarrasser.</li></ul>"},{"i":"04b275950ac4","n":1,"o":"1-9","u":"Définition","t":"Connaître la notion d’empathie clinique","q":"Quels sont les bénéfices cliniques de l'empathie pour la relation médecin-patient ?","a":"<ul><li>Améliore la <strong>communication médecin-patient</strong>.</li><li>Favorise l'<strong>adhésion thérapeutique</strong>.</li><li>Réduit l'<strong>anxiété et le stress</strong> du patient.</li><li>Humanise la <strong>relation de soin</strong>.</li></ul>"},{"i":"7d4980b7738f","n":1,"o":"1-9","u":"Définition","t":"Connaître la notion d’empathie clinique","q":"Quelles sont les quatre dimensions de l'empathie clinique ?","a":"<ul><li><strong>Empathie affective et cognitive</strong> : comprendre les affects et les pensées du patient.</li><li><strong>Empathie motivationnelle et comportementale</strong> : manifester au patient qu'il est compris.</li></ul>"},{"i":"e49dba31afd0","n":1,"o":"1-9","u":"Définition","t":"Connaître la notion d’empathie clinique","q":"Quelle est la définition de l'empathie clinique ?","a":"<p>L'empathie clinique est la capacité à <strong>comprendre les affects et les pensées d'autrui</strong>, et à <strong>faire comprendre au patient qu'il est compris</strong>.</p>"},{"i":"eb1d616221c8","n":1,"o":"1-9","u":"Définition","t":"Connaître la notion d’empathie clinique","q":"Quelle est la différence entre l'empathie, la sympathie et l'apathie ?","a":"<ul><li><strong>Empathie</strong> : comprendre l'autre sans se substituer à lui.</li><li><strong>Sympathie</strong> : ressentir la même chose qu'autrui.</li><li><strong>Apathie</strong> : incapacité à ressentir ou reconnaître l'émotion d'autrui.</li></ul>"}]};